import heapq

def run_order(deps):
    jobs = set(deps)
    for pre in deps.values():
        jobs.update(pre)
    after = {j: [] for j in jobs}
    indeg = {j: 0 for j in jobs}
    for job, pre in deps.items():
        for p in pre:
            after[p].append(job)
            indeg[job] += 1
    ready = [j for j in jobs if indeg[j] == 0]
    heapq.heapify(ready)
    order = []
    while ready:
        u = heapq.heappop(ready)
        order.append(u)
        for v in after[u]:
            indeg[v] -= 1
            if indeg[v] == 0:
                heapq.heappush(ready, v)
    return order if len(order) == len(jobs) else None
